-- Reemplazo completo del módulo de Ventas con la planilla actualizada
-- (PLANILLA_DE_SEGUIMIENTO (9).xlsx). Revisar antes de correr.
-- 61 prospectos, 64 oportunidades (deduplicadas de 110 filas crudas),
-- 1 seguimiento inicial por oportunidad.

-- Corta con un error claro si Romina no existe con ese nombre exacto en perfiles.
do $$
begin
  if not exists (select 1 from perfiles where nombre_completo = 'Romina Najun') then
    raise exception 'No se encontró un perfil con nombre_completo = ''Romina Najun''. Revisá el nombre exacto en la tabla perfiles antes de continuar.';
  end if;
end $$;

-- =========================================================
-- 0. Borrar todo lo cargado del módulo de Ventas
-- =========================================================
-- crm_oportunidades y crm_seguimientos tienen "on delete cascade" desde
-- crm_prospectos, así que este delete se lleva todo lo relacionado.
delete from crm_prospectos;

